practice.solution:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const n = Number(lines[0]);

let above = 0;
for (const [i, line] of lines.slice(1, n + 1).entries()) {
  const scores = line.trim().split(/\s+/).map(Number);
  const average = scores.reduce((acc, x) => acc + x, 0) / scores.length;
  if (average > 80) {
    above++;
  }
  console.log(`Student ${i + 1}: ${average.toFixed(2)}`);
}
console.log(`Above 80: ${above}`);
